def remove_invalid_parentheses_brute(s):
    n = len(s)
    best = []
    best_len = -1
    for mask in range(1 << n):                          # every subset of characters to keep
        kept = ''.join(s[i] for i in range(n) if mask & (1 << i))
        if is_valid(kept):
            if len(kept) > best_len:
                best_len = len(kept)
                best = [kept]
            elif len(kept) == best_len and kept not in best:
                best.append(kept)
    return best

