def is_valid(string):
    count = 0
    for c in string:
        if c == '(':
            count += 1
        elif c == ')':
            count -= 1
            if count < 0:
                return False
    return count == 0

def remove_invalid_parentheses(s):
    level = [s]
    seen = {s}
    while True:
        valid = [x for x in level if is_valid(x)]
        if valid:
            return valid                                    # first level with any valid string
        next_level = []
        for string in level:
            for i in range(len(string)):
                if string[i] not in '()':
                    continue
                candidate = string[:i] + string[i+1:]           # remove one paren
                if candidate not in seen:
                    seen.add(candidate)
                    next_level.append(candidate)
        level = next_level
        if not level:
            return ['']

