import java.util.*;

public class Main {
    static boolean isValid(String s) {
        int count = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') count++;
            else if (c == ')') { count--; if (count < 0) return false; }
        }
        return count == 0;
    }

    static List<String> removeInvalidParentheses(String s) {
        List<String> level = new ArrayList<>();
        level.add(s);
        Set<String> seen = new HashSet<>();
        seen.add(s);
        while (true) {
            List<String> valid = new ArrayList<>();
            for (String x : level) if (isValid(x)) valid.add(x);
            if (!valid.isEmpty()) return valid;                 // first level with any valid string
            List<String> next = new ArrayList<>();
            for (String str : level) {
                for (int i = 0; i < str.length(); i++) {
                    if (str.charAt(i) != '(' && str.charAt(i) != ')') continue;
                    String cand = str.substring(0, i) + str.substring(i + 1);  // remove one paren
                    if (seen.add(cand)) next.add(cand);
                }
            }
            level = next;
            if (level.isEmpty()) return Collections.singletonList("");
        }
    }
}

