#include <bits/stdc++.h>
using namespace std;

bool isValid(const string& s) {
    int count = 0;
    for (char c : s) {
        if (c == '(') count++;
        else if (c == ')') { count--; if (count < 0) return false; }
    }
    return count == 0;
}

vector<string> removeInvalidParentheses(string s) {
    vector<string> level = {s};
    unordered_set<string> seen = {s};
    while (true) {
        vector<string> valid;
        for (auto& x : level) if (isValid(x)) valid.push_back(x);
        if (!valid.empty()) return valid;                        // first level with any valid string
        vector<string> next;
        for (auto& str : level) {
            for (int i = 0; i < (int)str.size(); i++) {
                if (str[i] != '(' && str[i] != ')') continue;
                string cand = str.substr(0, i) + str.substr(i + 1);  // remove one paren
                if (seen.insert(cand).second) next.push_back(cand);
            }
        }
        level = next;
        if (level.empty()) return {""};
    }
}
